/* LORUN: a deferred callback queued on an LO (a function, its argument and the next record of the LO's list)
   (inferred from the fields).
   Layout from src/game/object/brx/LoadOptionFromBrx__FPvP5EOPIDiP18CBinaryInputStream.cpp (28 copies in Lilly ports) */
struct LORUN
{
      void (*pfn)(LO *plo, void *pv);   /* the callback */
      void *argument; /* its argument */
      LORUN *next;         /* next record in the LO's list */
};

/* LOROOT: the record shared by an object hierarchy: its topmost object and the links of the world's root list and
   busy list.
   Layout from src/game/gameplay/player/stepplayer/GetHeroInteractDistance.cpp (28 copies in Lilly ports) */
struct LOROOT
{
      LO *topObject; /* the topmost ancestor of the hierarchy */
      DLE rootLink; /* link in the world's list of hierarchy roots */
      DLE busyLink;  /* link in the world's list of busy (active) hierarchies */
};

/* LOUPD: an entry of the per-frame update list (SW::aloupd): flags and the object (sw.cpp, render.cpp). sly2/sw.h
   defines the same struct under the same guard (LO's tagged update word points at one), so either header may come
   first. */
#ifndef SLY2_STRUCT_LOUPD
#define SLY2_STRUCT_LOUPD
struct LOUPD
{
      int grf;
      LO *plo;
};
#endif

